import re
def money(x):
    if x is None or (isinstance(x,float) and x!=x): return float('nan')
    if isinstance(x,(int,float)): return float(x)
    s=str(x).strip().lower().replace('đ','').replace('₫','').replace('vnd','').replace(' ','')
    if not s: return float('nan')
    m=re.fullmatch(r'(\d+)tr(\d*)',s)
    if m: return int(m.group(1))*1e6+(int(m.group(2).ljust(3,'0')[:3])*1e3 if m.group(2) else 0)
    m=re.fullmatch(r'([\d.,]+)tr',s)
    if m: return float(m.group(1).replace(',','.'))*1e6
    m=re.fullmatch(r'([\d.,]+)k',s)
    if m: return float(m.group(1).replace(',','.'))*1e3
